/// <summary>
/// Feedback sent from the handheld (Problem / Idea / Question), with the screen, app version,
/// worker and warehouse it came from, the app's recent log and a screenshot (JPEG, in the
/// record). Reviewed on the Mobile feedback form; Status and Reply go back to the worker.
/// One list for the environment, like the device fleet.
/// </summary>
public class HSMobileOpsFeedback extends common
{
}

Method.Source:
public static HSMobileOpsFeedback findByFeedbackId(str _feedbackId, boolean _forUpdate = false)
{
    HSMobileOpsFeedback feedback;

    if (_feedbackId)
    {
        feedback.selectForUpdate(_forUpdate);
        select firstonly feedback where feedback.FeedbackId == _feedbackId;
    }
    return feedback;
}
